#pragma once

const char WEB_PAGE_HTML[] = R"=====(<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ESP32 USB PD Control</title>
<style>
:root{--bg:#0f1420;--card:#1a2233;--card2:#212c42;--txt:#e8edf7;--mut:#8ea0bf;--acc:#4da3ff;--ok:#37c978;--warn:#f0b429;--err:#ef5b5b}*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:var(--bg);color:var(--txt);padding:16px;max-width:900px;margin:auto}h1{font-size:1.3rem;margin-bottom:4px}.sub,.hint{color:var(--mut);font-size:.86rem;line-height:1.45}.card{background:var(--card);border:1px solid #2b3a50;border-radius:12px;padding:16px;margin-bottom:14px}.card h2{font-size:1rem;margin-bottom:10px;color:var(--acc)}.row{display:flex;flex-wrap:wrap;gap:10px}.chip{display:inline-flex;align-items:center;gap:6px;background:var(--card2);border-radius:999px;padding:5px 12px;font-size:.8rem;color:var(--mut)}.dot{width:8px;height:8px;border-radius:50%;background:var(--mut)}.dot.ok{background:var(--ok)}.dot.err{background:var(--err)}.dot.warn{background:var(--warn)}#status{border-left:4px solid var(--mut);padding:11px 12px;border-radius:8px;background:var(--card2);font-size:.9rem;line-height:1.45}#status.s-pending{border-color:var(--warn)}#status.s-ready{border-color:var(--ok)}#status.s-rejected,#status.s-timeout,#status.s-disconnected{border-color:var(--err)}#warning{display:none;background:#422b12;border:1px solid var(--warn);color:#ffe0a3;border-radius:8px;padding:11px 12px;margin-bottom:14px;font-size:.88rem}.pdo-list{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}.pdo{flex:1 1 145px;background:var(--card2);border:1px solid #2b3a50;border-radius:10px;padding:12px;cursor:pointer;text-align:center}.pdo:hover{border-color:var(--acc)}.pdo.sel{border-color:var(--ok);box-shadow:0 0 0 1px var(--ok)}.pdo.dis{opacity:.45;cursor:not-allowed}.pdo .v{font-size:1.25rem;font-weight:700}.pdo .i{color:var(--mut);font-size:.8rem;margin-top:3px}.step{border-top:1px solid #2b3a50;margin-top:16px;padding-top:14px}.step h3{font-size:.9rem;margin-bottom:8px}.step.disabled{opacity:.45}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.control{background:var(--card2);border-radius:10px;padding:12px}.label{display:flex;justify-content:space-between;font-size:.85rem;color:var(--mut);gap:8px}.label b{color:var(--txt)}input[type=range]{width:100%;accent-color:var(--acc);margin:8px 0}button{background:var(--acc);border:0;color:#08111f;font-weight:700;border-radius:8px;padding:10px 18px;font-size:.9rem;cursor:pointer}button:disabled{background:#3a4a63;color:var(--mut);cursor:not-allowed}.outline{background:transparent;color:var(--acc);border:1px solid var(--acc)}#error{display:none;background:#3a1c1c;border:1px solid var(--err);color:#ffc9c9;border-radius:8px;padding:10px 12px;margin-bottom:14px;font-size:.85rem}.mono{font-variant-numeric:tabular-nums}.value-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.value{background:var(--card2);border-radius:8px;padding:10px}.value span{display:block;color:var(--mut);font-size:.78rem}.value b{font-size:1.05rem}
</style>
</head>
<body>
<h1>ESP32 USB PD Control</h1>
<div class="sub">Monitor the charger and request one of its advertised power modes.</div>
<div id="error"></div><div id="warning">No recent communication with the charger. The controls are disabled. Check the cable and charger, then request fresh capabilities.</div>
<div class="card"><h2>Connection and protocol status</h2><div class="row" style="margin-bottom:10px"><span class="chip"><span id="d-server" class="dot"></span>Web interface</span><span class="chip"><span id="d-wifi" class="dot"></span><span id="wifi">Wi-Fi</span></span><span class="chip"><span id="d-charger" class="dot"></span>Charger</span><span class="chip mono">Last communication: <b id="last">&mdash;</b></span></div><div id="status" class="s-none">Waiting for charger information...</div></div>
<div class="card"><h2>Charger output</h2><div class="hint">The charger does not report a direct voltage/current measurement through the messages currently implemented. After a successful negotiation, the values below are the negotiated values, not an electrical measurement.</div><div class="value-grid" style="margin-top:10px"><div class="value"><span>Voltage</span><b id="actual-v">&mdash;</b></div><div class="value"><span>Current limit</span><b id="actual-i">&mdash;</b></div><div class="value"><span>Measurement</span><b id="actual-source">Not reported</b></div></div></div>
<div class="card"><h2>PPS status (live)</h2><div class="hint">Periodically queries the charger with Get_PPS_Status. Per the USB PD specification this only works while a PPS power contract is active. Polling is off by default.</div><div style="margin:10px 0"><label><input type="checkbox" id="pps-toggle"> Enable PPS status polling</label></div><div id="pps-status-body"></div></div>
<div class="card"><h2>Power request</h2><div class="step"><h3>Step 1 &mdash; Select a mode</h3><div class="hint">Choose one advertised fixed mode or the PPS mode. No request is sent at this step.</div><div id="pdos" class="pdo-list"></div></div><div id="step2" class="step disabled"><h3>Step 2 &mdash; Select voltage and current</h3><div id="fixed-controls" class="controls" style="display:none"><div class="control"><div class="label"><span>Selected voltage</span><b id="fixed-v">&mdash;</b></div><div class="hint" id="fixed-limit"></div></div><div class="control"><div class="label"><span>Requested current</span><b id="fixed-i">&mdash;</b></div><input id="fixed-slider" type="range"></div></div><div id="pps-controls" class="controls" style="display:none"><div class="control"><div class="label"><span>Available voltage range</span><b id="pps-v-range">&mdash;</b></div><input id="pps-v" type="range"><div class="label"><span>Selected voltage</span><b id="pps-v-value">&mdash;</b></div></div><div class="control"><div class="label"><span>Available current range</span><b id="pps-i-range">&mdash;</b></div><input id="pps-i" type="range"><div class="label"><span>Selected current</span><b id="pps-i-value">&mdash;</b></div></div></div></div><div id="step3" class="step disabled"><h3>Step 3 &mdash; Apply and check the result</h3><div class="hint">Press the button only after selecting all required values. The result will appear above and the button remains locked while the charger is responding.</div><div style="margin-top:10px"><button id="apply" disabled onclick="applyRequest()">Apply selected power mode</button></div></div><div style="margin-top:14px"><button id="refresh" class="outline" onclick="refreshCaps()">Request fresh capabilities</button></div></div>
<div class="sub mono" id="foot"></div>
<script>
let state=null,lastFetchOk=false,selected=null;
const $=id=>document.getElementById(id);
function dot(id,c){$(id).className="dot"+(c?" "+c:"")}function fmtMs(ms){if(ms===null||ms<0)return"—";if(ms<2000)return"just now";return Math.round(ms/1000)+" s ago"}function showError(t){$("error").textContent=t;$("error").style.display=t?"block":"none"}function fresh(p){return p.charger_seen&&p.last_rx_ms>=0&&p.last_rx_ms<10000&&p.pdos.length>0}function busy(p){return(p.req.state==="pending"||p.req.state==="accepted")&&p.req.age_ms<3000}
function statusText(p,dis){if(dis)return["s-disconnected","No recent communication with the charger. Controls are disabled until fresh Source Capabilities are received."];switch(p.req.state){case"pending":return["s-pending","Request sent. Waiting for the charger to accept it..."];case"accepted":return["s-pending","Request accepted. Waiting for the charger to confirm that the new power level is ready..."];case"ready":return["s-ready","Power mode accepted and ready. The values shown in Charger output are the negotiated limits, not a measurement."];case"rejected":return["s-rejected","The charger rejected this request. The previous power mode remains active."];case"timeout":return["s-timeout","The charger did not answer this request. Check the cable and connection, then try again."];default:return["s-none","Charger connected. Select a mode to begin the three-step request."]}}
function render(){const p=state.pd,ok=fresh(p),isBusy=busy(p);$("foot").textContent="Uptime: "+Math.floor(state.uptime_s/60)+" min "+Math.floor(state.uptime_s%60)+" s";dot("d-server",lastFetchOk?"ok":"err");dot("d-wifi",state.wifi.connected?"ok":"err");$("wifi").textContent=state.wifi.connected?"Wi-Fi: "+state.wifi.ip:"Wi-Fi disconnected";dot("d-charger",ok?"ok":(p.charger_seen?"warn":"err"));$("last").textContent=p.charger_seen?fmtMs(p.last_rx_ms):"—";$("warning").style.display=ok?"none":"block";const[s,t]=statusText(p,!ok);$("status").className=s;$("status").innerHTML=t;$("refresh").disabled=!state.wifi.connected||isBusy;
const negotiated=p.req.state==="ready"&&p.req.mv>0;$("actual-v").textContent=negotiated?(p.req.mv/1000).toFixed(2)+" V":"—";$("actual-i").textContent=negotiated?(p.req.ma/1000).toFixed(2)+" A":"—";$("actual-source").textContent=negotiated?"Negotiated value":"Not reported";
const q=p.pps_poll,qe=$("pps-toggle");qe.checked=q.enabled;let qb="";
if(!q.enabled)qb='<div class="hint">Polling is disabled. Enable it above to read voltage, current and status reported by the charger during a PPS negotiation.</div>';
else if(q.state==="gated")qb='<div class="hint">Waiting for an active PPS contract: Get_PPS_Status is only valid while the negotiated power mode is PPS and ready. Apply a PPS mode first.</div>';
else if(q.state==="unsupported")qb='<div class="hint" style="color:var(--warn)">The charger did not answer Get_PPS_Status (or answered Not Supported). PPS status reporting is not available with this charger.</div>';
else if(q.state==="waiting")qb='<div class="hint">Waiting for the first PPS status answer...</div>';
else{const stale=q.age_ms===null||q.age_ms>3000;qb='<div class="value-grid"><div class="value"><span>Reported voltage</span><b class="mono">'+(q.mv/1000).toFixed(1)+' V</b></div><div class="value"><span>Reported current</span><b class="mono">'+(q.ma/1000).toFixed(2)+" A</b></div><div class='value'><span>Status</span><b>"+["Standby","Compliant","Reserved","Error"][q.code]+"</b></div><div class='value'><span>Age</span><b class='mono'>"+(q.age_ms/1000).toFixed(0)+" s ago</b></div></div>"+(stale?'<div class="hint" style="color:var(--warn);margin-top:8px">No recent PPS status: the charger stopped answering Get_PPS_Status.</div>':"")}
$("pps-status-body").innerHTML=qb;
$("pdos").innerHTML="";p.pdos.forEach(o=>{const d=document.createElement("div");d.className="pdo"+(selected&&selected.pos===o.pos?" sel":"")+(ok?"":" dis");d.innerHTML=o.type==="fixed"?'<div class="v">'+(o.mv/1000)+" V</div><div class='i'>up to "+(o.ma/1000).toFixed(2)+" A</div>":'<div class="v">PPS</div><div class="i">position '+o.pos+"</div>";d.onclick=()=>{if(ok&&!isBusy){selected=o;render()}};$("pdos").appendChild(d)});
const chosen=selected&&p.pdos.find(o=>o.pos===selected.pos),hasChosen=!!chosen&&ok;$("step2").className="step"+(hasChosen?"":" disabled");$("step3").className="step"+(hasChosen?"":" disabled");$("apply").disabled=!hasChosen||isBusy;if(chosen&&chosen.type==="fixed"){ $("fixed-controls").style.display="grid";$("pps-controls").style.display="none";$("fixed-v").textContent=(chosen.mv/1000)+" V";$("fixed-limit").textContent="Available current: up to "+(chosen.ma/1000).toFixed(2)+" A";const f=$("fixed-slider");f.min=200;f.max=chosen.ma;f.step=10;if(!f.value||+f.value>chosen.ma)f.value=chosen.ma;$("fixed-i").textContent=(f.value/1000).toFixed(2)+" A"}else if(chosen&&chosen.type==="pps"){ $("fixed-controls").style.display="none";$("pps-controls").style.display="grid";const v=$("pps-v"),i=$("pps-i");v.min=chosen.min_mv;v.max=chosen.max_mv;v.step=20;if(!v.value||+v.value<chosen.min_mv||+v.value>chosen.max_mv)v.value=Math.min(Math.max(5000,chosen.min_mv),chosen.max_mv);i.min=200;i.max=chosen.ma;i.step=50;if(!i.value||+i.value>chosen.ma)i.value=chosen.ma;$("pps-v-range").textContent=(chosen.min_mv/1000).toFixed(2)+"–"+(chosen.max_mv/1000).toFixed(2)+" V";$("pps-i-range").textContent="0.20–"+(chosen.ma/1000).toFixed(2)+" A";$("pps-v-value").textContent=(v.value/1000).toFixed(2)+" V";$("pps-i-value").textContent=(i.value/1000).toFixed(2)+" A"}else{$("fixed-controls").style.display="none";$("pps-controls").style.display="none"}}
function applyRequest(){if(!selected)return;const p=state.pd,chosen=p.pdos.find(o=>o.pos===selected.pos);if(!chosen)return;if(chosen.type==="fixed")sendRequest({mode:"fixed",object:chosen.pos,mv:chosen.mv,ma:+$("fixed-slider").value});else sendRequest({mode:"pps",object:chosen.pos,mv:+$("pps-v").value,ma:+$("pps-i").value})}
function sendRequest(body){showError("");fetch("/api/request",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}).then(async r=>{const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||"The request was rejected.");poll()}).catch(e=>{showError(e.message);poll()})}function refreshCaps(){showError("");fetch("/api/refresh",{method:"POST"}).then(r=>{if(!r.ok)throw Error("Could not request charger capabilities.")}).catch(e=>showError(e.message))}
function poll(){const c=new AbortController(),timer=setTimeout(()=>c.abort(),2500);fetch("/api/status",{signal:c.signal}).then(async r=>{clearTimeout(timer);if(!r.ok)throw Error("HTTP "+r.status);state=await r.json();lastFetchOk=true;render();setTimeout(poll,busy(state.pd)?400:1000)}).catch(()=>{clearTimeout(timer);lastFetchOk=false;dot("d-server","err");$("warning").style.display="block";showError("The ESP32 status endpoint is not responding. Check the Wi-Fi connection.");setTimeout(poll,3000)})}
$("fixed-slider").oninput=()=>$("fixed-i").textContent=($("fixed-slider").value/1000).toFixed(2)+" A";$("pps-v").oninput=()=>$("pps-v-value").textContent=($("pps-v").value/1000).toFixed(2)+" V";$("pps-i").oninput=()=>$("pps-i-value").textContent=($("pps-i").value/1000).toFixed(2)+" A";$("pps-toggle").onchange=()=>{fetch("/api/pps_poll",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({enabled:$("pps-toggle").checked})}).catch(()=>showError("Could not change PPS polling setting."))};poll();
</script>
</body>
</html>)=====";
